validator:
function validate(input) {
  const [{ Logs = [] }] = input;
  const ids = new Set();
  for (const [id, num] of Logs) {
    if (id === null) return 'Every log entry needs an id.';
    if (ids.has(id)) return `id ${id} appears twice in Logs.`;
    if (num === null) return `Entry ${id} needs a num.`;
    ids.add(id);
  }
  for (let id = 1; id <= Logs.length; id++) if (!ids.has(id)) return `The ids must be 1 to ${Logs.length} with no gaps; ${id} is missing.`;
  return null;
}

generator:
function generate(rand, size) {
  const small = size === 'small';
  const count = small ? Math.floor(rand() * 9) : 2000;
  // A small pool and a high chance of repeating the previous number make runs of every length common.
  const pool = small ? [1, 2, 3, 0, -1] : Array.from({ length: 40 }, (_, i) => i - 5);
  const rows = [];
  let previous = null;
  for (let id = 1; id <= count; id++) {
    const num = previous !== null && rand() < 0.55 ? previous : pool[Math.floor(rand() * pool.length)];
    rows.push([id, num]);
    previous = num;
  }
  // Rows are stored in a shuffled order so that only the ids give the sequence.
  for (let i = rows.length - 1; i > 0; i--) {
    const j = Math.floor(rand() * (i + 1));
    [rows[i], rows[j]] = [rows[j], rows[i]];
  }
  return [{ Logs: rows }];
}
